"""Portable evaluation reports: embedded data, local frames, no network fetches."""

from __future__ import annotations

import copy
import html
import json
from pathlib import PurePosixPath
from urllib.parse import quote, urlsplit


def _frame_path(value: object) -> str | None:
    if not isinstance(value, str) or "\\" in value or urlsplit(value).scheme:
        return None
    path = PurePosixPath(value)
    if path.is_absolute() or ".." in path.parts or not path.parts:
        return None
    return "/".join(quote(part, safe="-_.") for part in path.parts)


def render_report(result: dict, spec: dict) -> str:
    """Render a standalone document; image paths stay relative to the run bundle."""
    payload = copy.deepcopy(result)
    for episode in payload.get("episodes", []):
        for frame in episode.get("frames", []):
            frame["path"] = _frame_path(frame.get("path"))
    data = json.dumps({"result": payload, "spec": spec}, allow_nan=False).replace("<", "\\u003c")
    data = data.replace(">", "\\u003e").replace("&", "\\u0026")
    data = data.replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    title = html.escape(str(spec.get("name", "Robot Worlds evaluation")))
    episodes = result.get("episodes", [])
    status, label = "recorded", "Evaluation recorded"
    if len(episodes) == 1:
        episode = episodes[0]
        rubric = episode.get("rubric", {})
        if episode.get("status") != "completed":
            status, label = "invalid", "Attempt interrupted or invalid"
        elif rubric.get("status") not in {"passed", "failed"}:
            status, label = "unscorable", "Insufficient evidence"
        elif rubric.get("success") is True and rubric.get("status") == "passed":
            status, label = "passed", "Task completed"
        else:
            status, label = "failed", "Task incomplete"
    return (_TEMPLATE.replace("__RUN_CLASS__", status).replace("__RUN_LABEL__", label)
            .replace("__TITLE__", title).replace("__DATA__", data))


_TEMPLATE = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>__TITLE__ · Evaluation</title>
<style>
:root{color-scheme:dark;--ink:#dcdfe9;--muted:#8a92a5;--line:#2a2f3c;--green:#9eb8df;--paper:#101217;--red:#e4a5a0;--amber:#d5bc89}*{box-sizing:border-box}body{margin:0;background:var(--paper);font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--ink)}button,select{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #56a989;outline-offset:3px}.report-header{padding:26px 34px;background:#161920;border-bottom:1px solid var(--line);display:flex;gap:24px;align-items:center;justify-content:space-between}.eyebrow{font-size:10px;letter-spacing:.15em;font-weight:500;text-transform:uppercase;color:var(--green)}h1{font-size:25px;line-height:1.25;margin:7px 0}h2{font-size:16px;margin:0}p{margin:7px 0}.muted{color:var(--muted)}.mono{font-family:ui-monospace,SFMono-Regular,monospace;font-size:11px;overflow-wrap:anywhere}.shell{max-width:1520px;margin:auto;padding:24px 30px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:22px}.stat{border:1px solid var(--line);border-radius:10px;background:#161920;padding:16px}.stat strong{display:block;font-size:25px;font-weight:500;margin-top:5px}.stat span{color:var(--muted);font-size:12px}.layout{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(310px,1fr);gap:20px;align-items:start}.card{background:#161920;border:1px solid var(--line);border-radius:12px;overflow:hidden}.card-head{padding:17px 20px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:15px}.pill{display:inline-flex;align-items:center;border-radius:5px;padding:4px 8px;font-size:11px;font-weight:500;background:#252b39;color:#a3aec4}.pill.passed{background:#1b3329;color:var(--green)}.pill.failed{background:#392426;color:var(--red)}.pill.unscorable,.pill.invalid{background:#3c3221;color:var(--amber)}.replay{aspect-ratio:4/3;background:#11141b;display:flex;align-items:center;justify-content:center;position:relative}.replay img{width:100%;height:100%;object-fit:contain}.replay-empty{padding:40px;text-align:center;color:var(--muted)}.replay-overlay{position:absolute;bottom:12px;left:12px;background:#142b24d9;color:#fff;font-size:11px;padding:5px 9px;border-radius:5px}.timeline{padding:14px 18px;border-top:1px solid var(--line)}.timeline-top{display:flex;align-items:center;gap:12px;margin-bottom:10px}input[type=range]{width:100%;accent-color:var(--green)}.button{padding:7px 11px;background:#161920;border:1px solid var(--line);border-radius:6px;color:var(--ink);text-decoration:none;white-space:nowrap}.criteria{max-height:760px;overflow:auto}.criterion{border-bottom:1px solid var(--line)}.criterion:last-child{border:0}.criterion-button{background:#161920;border:0;padding:16px 18px;display:flex;gap:12px;text-align:left;width:100%;align-items:flex-start}.criterion-button:hover,.criterion.selected .criterion-button{background:#232a39}.criterion-text{flex:1}.criterion-text strong{font-weight:500;display:block;line-height:1.5}.criterion-text small{display:block;margin-top:5px;color:var(--muted);font:11px ui-monospace,monospace}.evidence{padding:0 18px 18px;display:none}.criterion.selected .evidence{display:block}.evidence pre,.step pre{background:#10151f;border:1px solid #2c374b;border-radius:6px;padding:11px;font:11px/1.55 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere;max-height:280px;overflow:auto}.evidence-label{font-size:11px;font-weight:500;color:var(--green)}.task{padding:16px 20px}.episode-select{border:1px solid var(--line);padding:6px;border-radius:5px;background:#161920;max-width:55%}.error{background:#30291f;border:1px solid #58482f;border-radius:8px;padding:14px 18px;margin-bottom:18px;color:#d4bb91}.error[hidden]{display:none}.steps{margin-top:20px}.step{border-top:1px solid var(--line);padding:12px 18px}.step summary{cursor:pointer;display:flex;gap:10px;justify-content:space-between}.footer{display:flex;flex-wrap:wrap;gap:18px;margin:24px 0;color:var(--muted);font-size:11px}.footer a{color:var(--green)}.empty{padding:30px;color:var(--muted);text-align:center}.status-line{display:flex;align-items:center;gap:10px}details.provenance{margin-top:18px;padding:16px 20px}.provenance pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px;color:var(--muted)}@media(max-width:850px){.report-header{padding:20px;align-items:flex-start;flex-direction:column;gap:8px}.shell{padding:16px}.stats{grid-template-columns:repeat(2,1fr)}.layout{grid-template-columns:1fr}.criteria{max-height:none}h1{font-size:21px}}@media print{button,input,select{display:none}.layout{display:block}.card{margin-bottom:20px}.criteria{max-height:none}.evidence{display:block}.report-header{padding:0 0 20px}.shell{padding:15px 0}.replay{max-height:400px}}

h1{font-weight:530;letter-spacing:-.7px}h2{font-weight:500}.report-header{padding:22px 26px}.shell{padding:20px 24px}.card,.stat{border-radius:7px}.card-head{padding:14px 17px}.eyebrow{font-size:9px;color:#77859f}.episode-select{color:var(--ink)}.criterion-button{color:var(--ink)}
</style></head><body>
<header class="report-header"><div><div class="eyebrow">Robot Worlds / Evaluation report</div><h1 id="world-name">__TITLE__</h1><div class="muted" id="run-description"></div></div><div><div class="status-line"><span class="pill __RUN_CLASS__" id="run-status">__RUN_LABEL__</span><button class="button" id="download">Download result JSON</button></div><div class="mono muted" id="run-id" style="margin-top:9px"></div></div></header>
<main class="shell"><section class="stats" id="stats" aria-label="Evaluation summary"></section><p class="muted" id="termination" aria-label="Episode stop reason"></p><div class="error" id="error" hidden></div><div class="layout"><section><div class="card"><div class="card-head"><h2>Recorded replay</h2><select class="episode-select" id="episode" aria-label="Episode"></select></div><div class="replay"><img id="frame" alt="Recorded physics simulation frame" hidden><div class="replay-empty" id="no-frame">No frames were recorded for this episode.</div><span class="replay-overlay" id="frame-time" hidden></span></div><div class="timeline"><div class="timeline-top"><button class="button" id="play">Play</button><span class="mono" id="time-label"></span><span class="muted" style="font-size:11px;margin-left:auto">Nearest recorded frame</span></div><input type="range" id="scrub" min="0" max="0" value="0" step="1" aria-label="Replay frame"></div><div class="task"><div class="eyebrow">Task</div><p id="task"></p></div></div><div class="card steps"><div class="card-head"><h2>Robot tool decisions</h2><span class="muted" id="step-count"></span></div><div id="steps"></div></div></section><section><div class="card"><div class="card-head"><div><h2>Executable rubric</h2><div class="muted" style="font-size:11px;margin-top:4px">Select a check to inspect its evidence.</div></div><span class="pill" id="episode-status"></span></div><div class="criteria" id="criteria"></div></div><details class="card provenance"><summary>Protocol &amp; provenance</summary><pre id="provenance"></pre></details><div class="footer"><a id="trace-link">State trace</a><a id="transcript-link">Policy transcript</a><a id="result-link">Result JSON</a><span>Scored locally from recorded state.</span></div><p class="muted" id="measurement-note" style="font-size:11px"></p></section></div></main>
<script type="application/json" id="report-data">__DATA__</script>
<script>
(()=>{'use strict';const {result,spec}=JSON.parse(document.getElementById('report-data').textContent);const $=id=>document.getElementById(id);const text=(id,value)=>{$(id).textContent=value??'—'};const node=(tag,cls,value)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(value!==undefined)n.textContent=value;return n};const fmt=(n,d=1)=>Number.isFinite(Number(n))?Number(n).toFixed(d):'—';let episodeIndex=0,frameIndex=0,timer=null;const episodes=result.episodes||[];const defs=Object.fromEntries((spec.rubric||[]).map(c=>[c.id,c]));const served=/^\/api\/runs\/[^/]+\/report\/?$/.test(location.pathname);const fileBase=served?new URL(location.pathname.replace(/\/report\/?$/,'/files/'),location.origin):new URL('./',location.href);const fileURL=path=>new URL(path,fileBase).href;function badge(el,status,label){el.className='pill '+status;el.textContent=label||status.replaceAll('_',' ')}function verdict(e){if(e.status!=='completed')return['invalid',({policy_error:'Policy error',simulation_error:'Simulation error',grading_error:'Grading error',cancelled:'Interrupted'})[e.status]||e.status||'Invalid attempt'];if(e.rubric?.status==='unscorable')return['unscorable','Insufficient evidence'];return e.rubric?.success?['passed','Task completed']:['failed','Task incomplete']}
text('world-name',spec.name);text('task',spec.task);text('run-id',result.id);text('run-description',result.mode==='debug'?'Single episode · diagnostic run':'Repeated trials · independent episode resets');const summary=result.summary||{};const metrics=[['Task completion',summary.success_rate==null?'—':Math.round(summary.success_rate*100)+'%'],['Valid episodes',String(summary.valid??0)+' / '+String(summary.attempted??episodes.length)],['Invalid or interrupted',String(summary.invalid_or_interrupted??0)],['Inference wall time',fmt(episodes.reduce((a,e)=>a+(e.inference_seconds||0),0))+' s']];for(const [label,value]of metrics){const d=node('div','stat');d.append(node('span','',label),node('strong','',value));$('stats').append(d)}
episodes.forEach((e,i)=>{const option=node('option','',`Episode ${i+1} · seed ${e.seed} · ${verdict(e)[1]}`);option.value=i;$('episode').append(option)});$('episode').onchange=()=>{episodeIndex=Number($('episode').value);stop();renderEpisode()};function current(){return episodes[episodeIndex]||{frames:[],steps:[]}}function frames(){return(current().frames||[]).filter(f=>f.path)}function showFrame(index){const f=frames();frameIndex=Math.max(0,Math.min(index,f.length-1));$('scrub').value=frameIndex;const selected=f[frameIndex];$('frame').hidden=!selected;$('no-frame').hidden=!!selected;$('frame-time').hidden=!selected;if(selected){$('frame').src=fileURL(selected.path);text('frame-time',fmt(selected.time,2)+' s');text('time-label',`${fmt(selected.time,2)} / ${fmt(f.at(-1)?.time,2)} sim s`)}else{text('time-label','No replay frames')}}$('frame').onerror=()=>{$('frame').hidden=true;$('no-frame').hidden=false;$('no-frame').textContent='Recorded frame is unavailable. Keep report.html beside its episode folders.'};function evidenceTime(c,fallback){if(c.status==='failed')return c.evidence?.decisive_failure?.time??fallback;if(c.status==='unscorable')return c.evidence?.missing_measurements?.[0]?.time??fallback;return c.completion_time??fallback}function seek(time){const f=frames();if(!f.length)return;let nearest=0;f.forEach((frame,i)=>{if(Math.abs(frame.time-time)<Math.abs(f[nearest].time-time))nearest=i});stop();showFrame(nearest)}function stop(){if(timer)clearInterval(timer);timer=null;text('play','Play')}$('scrub').oninput=()=>{stop();showFrame(Number($('scrub').value))};$('play').onclick=()=>{if(timer){stop();return}if(!frames().length)return;if(frameIndex>=frames().length-1)showFrame(0);text('play','Pause');timer=setInterval(()=>{if(frameIndex>=frames().length-1)stop();else showFrame(frameIndex+1)},180)};
function renderEpisode(){const e=current();const reasons={policy_budget:'Policy decision budget reached',simulation_time_limit:'Simulation time limit reached',step_limit:'Step limit reached',policy_finished:'Policy ended the attempt',cancelled:'Cancelled',policy_error:'Policy error',simulation_error:'Simulation error'};text('termination','Stopped: '+(reasons[e.termination]||e.termination||'No stop reason recorded')+' · '+(e.steps||[]).length+' decisions');const f=frames();$('scrub').max=Math.max(0,f.length-1);$('scrub').disabled=!f.length;$('play').disabled=!f.length;showFrame(0);const [kind,label]=verdict(e);badge($('episode-status'),kind,label);const invalid=e.status!=='completed'||e.rubric?.status==='unscorable';$('error').hidden=!invalid;if(invalid){const err=e.error||e.grading_error;text('error',label+(err?' · '+(typeof err==='object'?(err.message||err.type):err):'')+'. This attempt is separate from ordinary task failure.')}text('measurement-note',e.rubric?.evidence?.measurement_limit||'');$('criteria').replaceChildren();const checks=e.rubric?.criteria||[];if(!checks.length)$('criteria').append(node('div','empty','No scored criteria are available.'));for(const c of checks){const row=node('div','criterion'),button=node('button','criterion-button'),copy=node('span','criterion-text'),b=node('span','pill');button.type='button';badge(b,c.status||'unscorable');copy.append(node('strong','',c.description||c.id),node('small','',`${c.evidence?.predicate||defs[c.id]?.predicate||''} · ${c.required?'required':'optional'}`));button.append(copy,b);const detail=node('div','evidence'),d=defs[c.id]||{};const metadata={object_id:c.evidence?.object_id,target_id:c.evidence?.target_id,mode:c.evidence?.mode,threshold:d.threshold,tolerance:d.tolerance,hold_seconds:c.evidence?.duration_required,after:c.evidence?.after,completion_time:c.completion_time};detail.append(node('div','evidence-label','Bindings & temporal rule'),node('pre','',JSON.stringify(metadata,null,2)),node('div','evidence-label','Recorded measurements'),node('pre','',JSON.stringify(c.evidence||{},null,2)));button.onclick=()=>{document.querySelectorAll('.criterion.selected').forEach(n=>n.classList.remove('selected'));row.classList.add('selected');seek(evidenceTime(c,f.at(-1)?.time??0))};row.append(button,detail);$('criteria').append(row)}$('steps').replaceChildren();const steps=e.steps||[];text('step-count',steps.length+' decisions');if(!steps.length)$('steps').append(node('div','empty','No robot decisions were recorded.'));for(const s of steps){const d=node('details','step'),summary=node('summary'),left=node('span','',`${s.step+1}. ${s.action?.tool||'unknown tool'}`),right=node('span','mono muted',fmt(s.time,2)+' sim s');summary.append(left,right);d.append(summary,node('pre','',JSON.stringify({arguments:s.action?.arguments,result:s.result,inference_seconds:s.inference_seconds},null,2)));summary.onclick=()=>seek(s.time||0);$('steps').append(d)}const dir=`episode-${String(e.index??episodeIndex).padStart(3,'0')}/`;$('trace-link').href=fileURL(dir+'trace.json');$('transcript-link').href=fileURL(dir+'transcript.json');$('result-link').href=fileURL('result.json');text('provenance',JSON.stringify({world_id:result.world_id,physical_id:result.physical_id,run_id:result.id,parent_run_id:result.parent_run_id,protocol:result.protocol,policy:result.policy,environment:result.environment,runtime:e.runtime,termination:e.termination,policy_usage:e.policy_usage,simulation_seconds:e.sim_seconds,inference_seconds:e.inference_seconds},null,2))}renderEpisode();$('download').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'}));const a=node('a');a.href=url;a.download='result.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};window.addEventListener('beforeunload',stop);
})();
</script></body></html>"""
